  color:#faf5eb;isolation:isolate;position:relative;
  background:radial-gradient(circle at 76% 38%,rgba(209,160,95,.22),transparent 30%),
   radial-gradient(ellipse at 13% 100%,rgba(94,116,111,.2),transparent 43%),
   linear-gradient(120deg,#131e21,#263738 67%,#19282b)
}
.advisor-page .advisor-hero:before{
  content:"";position:absolute;inset:0;pointer-events:none;
  background:repeating-linear-gradient(135deg,#fff0 0 92px,#ffffff05 93px,#fff0 94px)
