/* Premium documentary display for exact watches with no publishable photo.
   Decorative lines and layered surfaces are typographic, not watch artwork. */
.am-extra-art-no-photo{
  background:
    linear-gradient(112deg,transparent 0 25%,rgba(229,202,154,.055) 25.08%,transparent 25.4% 74%,rgba(229,202,154,.055) 74.08%,transparent 74.4%),
    radial-gradient(ellipse at 92% 5%,rgba(205,180,129,.23),transparent 53%),
    linear-gradient(145deg,#1c3b30 0%,var(--extra-shade) 58%,#0e2822 100%);
  border:1px solid #bba276;
  box-shadow:0 22px 55px rgba(18,39,29,.18),inset 0 0 0 7px rgba(255,255,255,.035);
}
.am-extra-art-no-photo::before{
  top:6%;right:-7%;width:48%;border:1px solid var(--extra-accent);
  border-radius:4px;opacity:.19;transform:rotate(33deg);box-shadow:0 0 0 20px #ffffff09;
}
.am-extra-art-no-photo::after{
  left:auto;right:12%;top:10%;width:28%;height:1px;
