   if(adjacent&&index>=0){
     const mk=(t,label)=>{const a=node('a','detail-adjacent-link');a.href=crossProduct(t.id);a.append(node('span','',label),node('strong','',t.brand+' '+t.model));return a};
     adjacent.replaceChildren();
