/* Atelier Montres — real photographed editorial highlights.
   Used by affiliation.html, the actual source for the SEO-generated homepage.
   No external font, image or JavaScript dependency. */
.home-featured .home-section-heading,
.home-info .home-section-heading{display:flex;align-items:end;justify-content:space-between;gap:25px;margin-bottom:30px}
.home-featured .home-section-heading>p{max-width:385px;color:#52665e;line-height:1.8;margin:0}
.home-featured{background:#fffdf8;padding:clamp(70px,8vw,110px) 0}
.home-featured-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:19px}
.home-product{min-width:0;border:1px solid #e1d9cc;border-radius:12px;overflow:hidden;background:#fff;
 box-shadow:0 8px 22px #16242612;display:flex;flex-direction:column}
.home-product-visual{display:grid;place-items:center;min-height:295px;padding:15px;
 background:radial-gradient(circle at 45% 40%,#fcfbf7,#e5e8e3 70%,#d5dcd6)}
.home-product:nth-child(2) .home-product-visual{background:radial-gradient(circle,#faf7f2,#dfd7cb 73%,#c9b9ac)}
.home-product:nth-child(3) .home-product-visual{background:radial-gradient(circle,#f8f8f4,#d3d9d8 72%,#bcc8c8)}
.home-product-visual img{height:265px;width:100%;object-fit:contain;filter:drop-shadow(0 12px 14px #10252238)}
.home-product-body{display:grid;gap:10px;padding:24px 23px 28px;flex:1}
.home-product-brand{font:700 10px/1.5 system-ui;letter-spacing:.16em;color:#805b34}
.home-product h3{font:400 29px/1.2 Georgia,serif;color:#223b38;margin:0}
.home-product p{color:#52645e;font-size:13px;line-height:1.7;margin:0}
.home-product a{align-self:end;margin-top:auto;padding-top:10px;color:#654825;font-weight:750;
 text-decoration:underline;text-underline-offset:5px;font-size:13px}
.home-featured-footer{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;
 gap:20px;margin-top:31px}
.home-featured-footer p{max-width:660px;color:#52655d;margin:0;font-size:12px;line-height:1.7}
.home-featured-footer .button{border-radius:6px;background:#253a38;border-color:#253a38;color:#fff}
.home-info{background:#ebe7dd;padding:clamp(68px,7vw,95px) 0}
.home-info-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}
.home-info-card{padding:clamp(26px,3.5vw,50px);border:1px solid #d7cfbf;
 border-radius:12px;background:#fcfaf4}
.home-info-card h3{font:400 clamp(27px,3.5vw,42px)/1.2 Georgia,serif;margin:0 0 16px}
.home-info-card p{color:#4d615a;font:400 14px/1.85 system-ui;margin:0 0 18px}
.home-info-card a{font-weight:750;color:#5b4426;text-underline-offset:5px}

.home-info .home-section-heading .overline,
.home-info .home-info-card .overline{color:#63472a}
body[data-experience=affiliate] .home-featured .home-section-heading h2{
  font:400 clamp(35px,4.8vw,61px)/1.1 Georgia,serif;
  letter-spacing:-.035em;color:#203432}
body[data-experience=affiliate] .home-featured .home-section-heading .overline{
  color:#795528}
body[data-experience=affiliate] .home-featured a:focus-visible,
body[data-experience=affiliate] .home-info a:focus-visible{
  outline:3px solid #b48239;outline-offset:4px}
.home-featured .home-product a{min-height:44px;display:inline-flex;align-items:center}
@media(max-width:850px){
  .home-featured-grid{gap:12px}
  .home-product-visual{min-height:250px}
  .home-product-visual img{height:220px}
  .home-info-card{padding:28px}
}
@media(max-width:650px){
  .home-featured-grid,.home-info-grid{grid-template-columns:1fr}
  .home-featured .home-section-heading{display:block}
  .home-featured .home-section-heading>p{margin-top:13px}
  .home-featured-footer{flex-direction:column;align-items:stretch}
  .home-featured-footer .button{min-height:48px}
  .home-product-visual{min-height:265px}
  .home-product-visual img{height:240px}
  .home-info{padding:65px 0}
  .home-featured{padding:70px 0}
}
@media(prefers-reduced-motion:reduce){
  .home-product,.home-product *{animation:none!important;transition:none!important}
}

/* Maison Atelier — visual system inspired by fine-watch editorial, original implementation. */
:root{--am-ink:#16251d;--am-cream:#f8f6f0;--am-warm:#eeeae1;--am-gold:#bc9c69;--am-line:#e4dfd5}
html{scroll-padding-top:95px}
.am-topline{background:#12231a;color:#ddccac;font-size:9px;letter-spacing:.18em;line-height:1.4}
.am-topline .wrap{min-height:34px;display:flex;align-items:center;justify-content:space-between;gap:10px}
.am-header{background:#172c20;border-bottom:1px solid #51615455;position:sticky;top:0;z-index:20;backdrop-filter:blur(15px)}
.am-header .brand{font:400 28px/1.1 Georgia,serif;letter-spacing:.015em;white-space:nowrap}
.am-header .header-inner{min-height:83px;height:auto;flex-wrap:wrap;padding-block:14px}
.am-header .navigation a{font-size:11px;letter-spacing:.13em}
.am-header .navigation a:hover{color:#e8c994}
.am-header .tag{border-color:#d5bd8b88}
.aff-hero{background:radial-gradient(ellipse at 78% 48%,#38544066 0%,transparent 42%),linear-gradient(140deg,#11241a,#21362a 67%,#152d22);overflow:hidden}
.aff-hero-inner{min-height:675px;gap:20px}
.aff-copy h1{font-size:clamp(52px,6.5vw,98px);letter-spacing:-.045em;font-weight:400;max-width:750px}
.aff-copy h1 em{font-weight:400;color:#e0c59a}
.aff-copy>.overline{color:#d9bc8f}
.aff-copy>.button{background:#d7b888;border-color:#d7b888}
.am-hero-art{height:620px;overflow:visible}
.am-stage-halo{position:absolute;border-radius:50%;width:480px;height:480px;border:1px solid #dbc39133;box-shadow:0 0 0 70px #ddd7ad0a,0 0 0 146px #e8d29f06}
.am-hero-watch{position:relative;width:100%;height:100%;display:flex;align-items:center;justify-content:center;filter:drop-shadow(23px 37px 26px #0007);transform:scale(1.15)}
.am-hero-watch svg{width:min(95%,425px);height:85%;max-height:570px}
.am-hero-label{position:absolute;bottom:35px;right:0;display:grid;gap:6px;align-items:center;text-align:right;color:#f4ead4}
.am-hero-label strong{font:400 18px Georgia,serif;letter-spacing:.1em}
.am-hero-label small{font-size:10px;letter-spacing:.07em;color:#bbcabc}
.am-hero-index{color:#c5a778;font-size:12px;letter-spacing:.25em}
.aff-tiers{background:#eeece4}
.aff-tier-grid{gap:1px}
.aff-tier-grid>a{background:#f5f2ea;border-bottom:2px solid transparent;transition:background .25s,border-color .25s}
.aff-tier-grid>a:hover,.aff-tier-grid>a:focus-visible{border-bottom-color:#a88954;background:#eae5d9}
.aff-tier-grid strong{font:400 clamp(30px,3.2vw,40px)/1.2 Georgia,serif;letter-spacing:-.025em}
